from collections import defaultdict

def simulate_tree(n, edges):
    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u-1].append(v-1)
        adj_list[v-1].append(u-1)

    def recursive_build(node, parent):
        for child in adj_list[node]:
            if child != parent:
                recursive_build(child, node)
                probs[node] = (1 - probs[child]) / 2

    probs = defaultdict(float)
    for node in range(n):
        if node in adj_list:
            recursive_build(node, -1)
        else:
            probs[node] = 1
    return probs

