from functools import lru_cache

@lru_cache(maxsize=None)
def max_change(ch, letter, position, count):
    if count == 1:
        return 0
    if position >= len(ch):
        return int(ch[0] != letter)
    max_replacement = max([max_change(s, letter, position+1, count-1) for s in ch])
    current_cost = max_change(ch[position] + 1, letter, position+1, count+1)
    return max(max_replacement, current_cost)

def solve(multiset, strings, changes):
    global_counter = max(changes) + sum(i for x in multiset for i in x)
    for i in range(len(multiset[0])):
        choices = set('*'.join(str(j, letter) for j, letter in zip(*strings)).split('*'))
        current_cost = global_counter
        for ai in changes:
            current_cost -= ai[i]
            new_multiset = [list(s) for s in multiset]
            for j, l in enumerate(ai):
                if l > 0:
                    new_multiset[j][i] = chr(ord('a') + multiset[j].index(letter))
            new_strings = [''.join(xs) for xs in new_multiset]
            for string in new_strings:
                current_cost += max_change(string, chr(ord('a') + i), 0, 1)
            current_cost += sum(i for x in multiset for i in x)
            if current_cost == 0:
                return 0
            if current_cost < global_cost:
                global_cost = current_cost
    return global_cost

