def solve(n: int, s: str, forbidden_hexed: str) -> int:
    if int(forbidden_hexed, base=2) == 0:
        return n**2  # If no indices are forbidden, the maximum is n * n

    # Convert forbidden set to index positions
    forbidden = [int(b) for b in forbidden_hexed]
    forbidden.insert(0, 0)  # Handle leading characters

    F = [0] * (len(forbidden) + 1)
    for i, f in enumerate(forbidden):
        F[i + 1] = s[i:].count(s[f - 1]) * (i + 1)

    # Precompute LCS (longest common subsequence) of s and a for each prefix
    dp = [[0] * (n + 1) for _ in range(len(F) + 1)]
    for i in range(len(F) + 1):
        for j in range(n + 1):
            if F[i] != 0 and i > F[i]:
                j -= 1
            if j == 0:
                dp[i][j] = F[i]
            elif F[i] > 0:
                dp[i][j] = max(dp[i][j - 1], F[i] + dp[i - int(F[i]), j - F[i]])
                if F[i] < j:
                    dp[i][j] = max(dp[i][j], F[i] + dp[int(j - F[i]), j - F[i] - F[i]])

    a = ""
    res = 0
    for i in range(n):
        a += s[i]
        if i + 1 > n - 1 - int(F[i]):
            a = s[: i + 1]
            F = [0] + F[:-1]
            for i in forbidden:
                if s[i - 2] == a[-1]:
                    F[i - 1] = max(F[i - 1], F[i])
                    if F[i + 1] > 0 or i < len(F):
                        res = max(res, F[i - 1] * F[i + 1] * int(a[-1] + a[-1]))
            a = s[i + 1:]
        elif i + 1 > n - 1:
            a = s[: i + 1]
            F = [0] + F[:-1]
            for i in forbidden:
                if s[i - 2] == a[-1]:
                    F[i - 1] = max(F[i - 1], F[i])
                    if F[i + 1] > 0 or i < len(F):
                        res = max(res, F[i - 1] * F[i + 1] * int(a[-1] + a[-1]))
            a = s[: i + 1]
    return res

