from collections import defaultdict

def determine_wall_duration(pair_boundary, wall_fragments, wall_start):
    """
    Function to determine the time duration when the pair of tourists won't see each other after the specified wall
    """

    wall_contents = []
    timeset = set()

    for _, _, time in wall_fragments:
        if time >= wall_start:
            wall_contents.append(time)

    for wall in wall_contents:
        left = max(0, pair_boundary - wall)
        right = min(pair_boundary, wall + wall_contents[-1] - 1)
        if left < right:
            timeset.add((wall - left) * (wall_contents[1] - wall_contents[0]) // 2)
            timeset.add((right - wall) * (wall_contents[-2] - wall_contents[-1]) // 2)
        if left == right:
            timeset.add((right - wall) * (wall_contents[1] - wall_contents[0]) // 2)

    return sum(timeset)

def count_non_visible_periods(count, log=None):
