        early_walls = wall_start - wall_range[0]

        wall_fragments[late_walls].append((early_walls, (wall_end - wall_range[1]) * (wall_start - (wall_range[0] - 1)) // 2))

    wall_contents = {}
    for _wall_start, walls_passing in wall_fragments.items():
        wall_info = 0
        curr_wall = 0

        while walls_passing:
            # Find the most recent wall able to cause a missing period
            if wall_info == _wall_start:
                if walls_passing:
                    curr_wall = walls_passing.pop()
            else:
                wall_info = _wall_start
            curr_wall, wall_info = determine_wall_duration(curr_wall, walls_passing, wall_info)
        wall_contents[_wall_start] = wall_info

    return max(wall_contents.values()) + 1

