from collections import defaultdict

def game_winner(game, m, q, queries):
    # Define a function to determine the winner of the game
    def winner(s, e, p, d):
        if game[s-1] >= d:
            return game[s-1] - d >= game[e] + d
        return True 

    # Add a dummy prefix to handle the initial move
    game.insert(0, 0)
    graph = defaultdict(list)
    for i in range(1, len(game)):
        if game[i-1] > 0:
            graph[game[i-1]].append((game[i], True))
            graph[game[i]].append((game[i], False))

    for i in range(1, len(game)):
        if game[i-1] > 0:
            graph[game[i-1]].append((game[i], True))
            graph[game[i]].append((game[i], False))

    for i in range(len(game)):
        if graph[game[i]]:
            o1 = []
            for edge in graph[game[i]]:
                start, prob = edge
                if winner(i + 1, i + 1 + m, prob, start):
                    o1.append('Next!')
                else:
                    o1.append('Impossible!')
            if 'IMPOSSIBLE!' in o1:
                continue
            else:
                graph[start].append((game[i+1], o1.index('IMPOSSIBLE!')))
                graph[start].append((0, o1.index('Next!')))
                break

    for i in range(q):
        if queries[i][0] == 1:
            game = game[queries[i][2]:] + game[:queries[i][2]]
        else:
            game_winner, game_winner_indexes = graph[game[queries[i][2]]]
            print('1' if game_winner and 'Next!' in game_winner_indexes else '2')
