from typing import List

def max_total_score(n: int, scores: List[int]) -> int:
    total_scores = []
    for i, score in enumerate(scores):
        total_scores.append((i+1)*score)
    if not total_scores:
        return 0
    total_scores.sort(reverse=True)
    total_score = sum(total_scores)
    count = len(total_scores)
    max_memo = total_score
    min_n_expensive = 0
    for i in range(1, count-1):
        temp = total_score - (total_scores[count-i-1] + total_scores[i+1])
        if temp > max_memo:
            max_memo = temp
            min_n_expensive = count - i
        elif temp < max_memo:
            break
        elif temp == max_memo:
            if min_n_expensive > i+1:
                min_n_expensive = i+1
    return total_score - min_n_expensive*total_scores[0]
