import sys
from collections import deque
from typing import List

def minimum_operations_to_good_sequence(test_cases: int, nodes: List[int]) -> int:
    if nodes[0] == 0:
        return 0
    if all(n == 0 for n in nodes):
        return -1
    n = len(nodes)
    dp = [[float('inf')] * n for _ in range(2)]
    dp[0][0] = 0
    dp[0][1] = 1
    que = deque([(0, 0), (0, 1)])
    while que:
        node, parity = que.popleft()
        if node == n - 1 and parity == 0:
            return -1  # Impossible to make the sequence good
        if parity == 1:
            if dp[parity][node] == float('inf'):
                if node - 1 >= 0 and nodes[node - 1] != nodes[-1]:
                    dp[parity][node - 1] = dp[1 - parity][node]
                    que.append((node - 1, clear_value(parity, nodes, node - 1, n - 1)))
                if node + 1 < n and nodes[node + 1] != nodes[0]:
                    dp[parity][node + 1] = clear_value(1 - parity, nodes, node + 1, n - 1)
                    que.append((node + 1, clear_value(1 - parity, nodes, node + 1, n - 1)))
        else:
            if dp[parity][node] == float('inf'):
                if node < n and nodes[node] != nodes[0]:
                    dp[parity][node + 1] = clear_value(parity, nodes, node, n - 1)
                    que.append((node, clear_value(parity, nodes, node, n - 1)))
                if node > 0 and nodes[node - 1] != nodes[-1]:
                    dp[parity][node - 1] = clear_value(0 - parity, nodes, node - 1, n - 1)
                    que.append((node - 1, clear_value(0 - parity, nodes, node - 1, n - 1)))
    return min(dp[0][i] for i in range(n))

def clear_value(parity, nodes, pos, index):
    if parity == 0:
        return min(nodes[index] - 1, nodes[pos] - 1)
    return min(nodes[index] - 1, nodes[pos] - 1) + 1

