import sys

def find_tables(K: int, Q: int, intervals: List[List[int]]) -> str:
    def check_tables(K: int, msbt: List[int], lsb: List[int], intervals: List) -> bool:
        for i in range(Q):
            low = intervals[i][0] >> (K-1)  # first K bits
            hi = intervals[i][1] << (K-1)  # last K bits
            if (lsb[low] & msbt[hi - 1] != intervals[i][2]):
                return False
        return True

    tables = []
    for i in range(2**K):
        tables.append([0]*2**K)
    used = [0]*2**K

    for i in range(Q):
        low, hi, val = intervals[i]
        used[low] = 1
        used[hi-1] = 1
        msbt = [0]*2**(K-1)
        lsb = [0]*(2**K)
        for k in range(K-1, -1, -1):
            if (used[hi >> k] & used[hi - hi << (K-1 - k)]) == 0 and used[hi - hi << (K-1 - k)] == 1:
                msbt[k] = hi >> (K-k)
                lsb[hi - hi << (K-1 - k)] = val
            else:
                break
        if (((hi >> (K-1)) // ((hi >> (K-1)) + 1)) == (hi >> (K-1)) + 1) and (hi == (hi >> (K-1)) + 1):
            tables[hi] = msbt
            tables[hi - 1] = lsb
        else:
            return 'impossible'

    satisfy = check_tables(K, tables[-1], tables[-2], intervals)
    if satisfy:
        for i in range(1, 2**K):
            tables[i] = tables[i-1]
        for i in range(len(tables)):
            sys.stdout.write(str(tables[i]))
            sys.stdout.write('\n')
    else:
        sys.stdout.write('impossible')
        return

