def read():
    return sys.stdin.readline().strip()

def solve(k, q):
    intervals = []
    msb_tables = [[] for _ in range(1 << k)]
    for i in range(q):
        l, r, v = map(int, read().split())
        intervals.append([l, r, v])
        msb_tables[get_high_bit(k, r)].append(v)
    tables = [dict()] * (1 << k)
    found = False
    for num, intervals in enumerate(intervals):
        if intervals[0] & (1 << k - 1):
            tables[num] = set()
            continue
        l = intervals[0]
        r = intervals[1]
        target = intervals[2]
        i = get_high_bit(k, r)
        for msb in msb_tables[i]:
            low_bits = l & ((1 << (k - 1)) - 1)
            if low_bits < target:
                low_bits |= (1 << k - 1)
            table = set([msb])
            table.add(low_bits)
            table |= tables[num]
            for table_i in table:
                tables[num].add(table_i)
            if low_bits in tables[num]:
                tables[num].discard(low_bits)
            if target in tables[num]:
                tables[num].discard(target)
        if len(tables[num]) == 1:
            found = True
            table = tables[num].pop()
            break
    if not found:
        return "impossible"
    else:
        return "possible\n{0}\n{1}".format(*tables)

def get_high_bit(k, num):
    """Helper function to find the highest set bit position of num in binary representation."""
    return 1 << (k - 1 - 1 & initial_bit_place(k, num))

def initial_bit_place(k, num):
    """Return the highest bit place for the given bit position. If uninitialized returns '0'."""
    return num >> ((k - 1) & added_bit_state(k, num))

def add_bit_state(k, num):
    """Helper function to let the number to have the bit in the bit place k."""
    return (num << 1) | 1

def initial_bit(k):
    """Initialize !! K == !! 1 !! and P == !! 1 !! gas slot upon start of function. """
    return add_bit_state(1, initial_bit_state(1))

def initial_bit_state(k):
    """Return P if initialize P, if no init then return state of LSB, highest set bit."""
    return (1 << added_bit_state(1, 0))

def added_bit_state(k, num):
    """Helper function for 'initial_bit_state' function given the current bit state."""
    return num >> num_bit_state(1, k)

def num_bit_state(k, num):
    """Return the place of bit in the LSB corresponding to initial bit state."""
    return n_bit_state(1, num)

def n_bit_state(k, num, bit=0):
    """Return the folded of a given place of the MSB for current binary number. """
    k -= bit
    return bit if k < 0 else (2 ** (add_bit_state(k + 1, num)))

