def find_permutation(A):
    """
    Finds the lexicographically smallest permutation P such that A can be obtained
    from P using the given rules.
    """
    n = len(A)
    result = [-1] * n
    stack, flag = [], 0

    for i in range(n):
        if A[i] == -1:
            while len(stack) > 1 and flag == 1:
                result[stack.pop()] = stack.pop() + 1
            result.append(stack.pop() + 1)
        else:
            result.append(stack.pop() + 1)
            while len(stack) > 0:
                if A[stack.pop()] > A[i]:
                    if not flag:
                        flag = 1
                    elif flag == 1:
                        flag = 2
                else:
                    if flag == 2:
                        result.append(stack.pop() + 1)
    for c, i in enumerate(A):
        if i == 0:
            while i == 0:
                if flag < 3:
                    break
                flag = 2
                while c > i:
                    if flag == 2:
                        result.append(stack.pop() + 1)
                    else:
                        result.append(stack.pop())
                        flag = 1
                    c -= 1
                    i = result.pop()

                result.append(stack.pop() + 1)
                flag = 1

    return result

