def LexicographicallySmallestPermutation(N, arr):
    # Check if the array can be generated
    for i in range(1, N):
        if arr[i] < min(N - 1, N - 1 - arr[i - 1]):
            return -1
    # If possible, find the lexicographically smallest permutation
    permutation = [i+1 for i in range(0, N-1)] + [-1]
    return permutation
