def find_max_occurrences(n, s, forbidden):
    max_occurrences = 0
    for i in range(n):
        if i in forbidden:
            continue
        for j in range(n):
            if s[j] != s[i] and j not in forbidden:
                max_occurrences = max(max_occurrences, i - j + 1)

    return max_occurrences

def find_a_length(n, s, forbidden):
    first_a = 0
    for i in range(n):
        if s[i] == 'a':
            first_a = i
            break

    a_length = 0
    for i in range(n):
        if i + a_length >= n:
            break
        if forbidden[i + a_length] == 0:
            a_length += 1

    return a_length

def solution(n, s, k):
    s = list(s)
    forbidden = [int(x) for x in k]  # Convert the string k to a list and convert characters to integers

    max_occurrences = find_max_occurrences(n, s, forbidden)
    a_length = find_a_length(n, s, forbidden)
    a_non_forbidden_length = n - max_occurrences - a_length

    return n * a_non_forbidden_length

