import sys

def solve(N, A):
    operations = 0
    while 0 in A:
        indices = [i for i, val in enumerate(A) if val == 0]
        min_diff = float('inf')
        for index in indices:
            adjacent_indices = [i for i in range(max(0, index-1), min(N, index+2))]
            for adj_index in adjacent_indices:
                if adj_index in indices:
                    continue
                if A[adj_index] == 1:
                    min_diff = min(min_diff, abs(index - adj_index))
        operations += min_diff
        A = [1 if i % 2 == 0 else 0 for i in range(N)]
    min_operations = len(A) // 2
    for i in indices:
        if A[i] == 1:
            A[i] = 0
    for i in indices:
        adjacent_indices = [(i + 1) % N, (i - 1) % N]
        for adj_index in adjacent_indices:
            if A[adj_index] == 1:
                min_operations -= 1
                A[adj_index] = 0
    return min_operations

