# The algorithm is implemented using the Union-Find data structure and path compression.

class UnionFind:
    def __init__(self):
        self.parent = [i for i in range(1000000)]
        self.ranks = [0] * 1000000

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX == rootY:
            return False
        if self.ranks[rootX] < self.ranks[rootY]:
            self.parent[rootX] = rootY
        elif self.ranks[rootX] > self.ranks[rootY]:
            self.parent[rootY] = rootX
        else:
            self.parent[rootY] = rootX
            self.ranks[rootX] += 1
        return True

