def find_lexicographically_smallest_permutation(N: int, A: List[int]) -> int:
    if N == 1 and A[0] == -1:
        return -1
    elif N == 1 and A[0] == 0:
        return -1
    elif N == 1:
        return 1

    stack = [0]
    new_array = []
    non_decreasing = True
    for i in range(N):
        if A[i] == -1:
            non_decreasing = True
            stack += [i]
        else:
            if A[i] > A[stack[-1]]:
                sub_array = A[stack[-2]:i]
                for index in reversed(stack):
                    while sub_array.index(min(sub_array, default=None)) > A[index]:
                        sub_array.remove(min(sub_array, default=None))
                        if not sub_array:
                            sub_array = []
                            break
                if sub_array:
                    if len(sub_array) > len(stack):
                        new_array = sub_array
                        stack += []
                        while non_decreasing and stack:
                            while sub_array[index] < sub_array[index - 1]:
                                new_array.remove(min(new_array, default=None))
                                if not new_array:
                                    new_array = []
                                    break
                                index -= 1
                                if not sub_array or sub_array[index] < new_array[-1]:
                                    new_array.remove(min(new_array, default=None))
                            if sub_array[index] < sub_array[index - 1]:
                                new_array.remove(min(new_array, default=None))
                                new_array.append(A[stack[-1]])
                                stack.append(i)
                                non_decreasing = False
                    else:
                        new_array = sub_array
                        stack = stack[:-1] + [i]
                        non_decreasing = False
                else:
                    if len(stack) == 1:
                        stack = [i]
                    else:
                        stack[-2:] = stack[-2:]
                stack = [i]
            else:
                non_decreasing = False

    if len(stack) > 1:
        stack = stack[-1:] + [i for i in range(N) if i not in stack]
    return 1 if non_decreasing else -1

