def isConvex(polygon):
    n = len(polygon)
    condition1 = True
    condition2 = True

    for i in range(n):
        x1 = polygon[i % n][0] - polygon[(i + 1) % n][0]
        y1 = polygon[i % n][1] - polygon[(i + 1) % n][1]
        x2 = polygon[(i + 1) % n][0] - polygon[(i + 2) % n][0]
        y2 = polygon[(i + 1) % n][1] - polygon[(i + 2) % n][1]

        cross_product1 = x1 * y2 - x2 * y1
        cross_product2 = x2 * y1 - x1 * y2

        if condition1 and not ((cross_product2 > 0) == (cross_product1 > 0)):
            return False
        if condition2 and not ((cross_product2 < 0) == (cross_product1 < 0)):
            return False

        condition1 &= (cross_product1 > 0)
        condition2 &= (cross_product2 > 0)

