    by the given method.
    """
    return all(A[i] == max(j for j in range(i) if A[j] > P[i]) for i in range(len(A)))

def find_smallest_valid_permutation(P, A):
    """
    Finds and returns the lexicographically smallest valid permutation P that
    can generate the given array A.
    """
    min_permutation = permutations(range(1, len(A)+1))
    for perm in min_permutation:
        if is_valid(perm[:P.index(-1)], A):
            print(' '.join(map(str, perm)))
            break
    else:
        print(-1)

def process_case(N, A):
    for i in range(N):
        if A[i] == -1:
            find_smallest_valid_permutation(A, A[:i] + [-1] + A[i+1:])
            break

def run_tests(num_tests):
    for _ in range(num_tests):
        T = int(input().strip())
        for _ in range(T):
            N = int(input().strip())
            A = list(map(int, input().strip().split()))
            process_case(N, A)

run_tests(2)  # Example input provided in the guidelines for testing
