from collections import deque

def play_game(b, players):
    moves = []
    index = 1
    while index < len(b):
        new_index = index
        while b[new_index] > 0 and new_index + m <= len(b):
            deque.append(moves, deque([new_index]))
            new_index += m
        index = new_index
    return [index] + moves

def make_move(index, b, players):
    index_ = index
    while b[index_] > 0:
        if players[index_] not in range(1, len(b)):
            return False
        players[index_] += 1
        b[index_] -= 1
    return True

def is_winner(players):
    return players[p1] - players[p2] < players[p2] - players[p1]

