from collections import defaultdict

def simulate_tree(n, params):
    edges = []
    n_nodes = n
    while n_nodes > 1:
        i = random.choice(range(n_nodes))
        j = random.choice(range(i + 1, n_nodes))
        edges.append((i, j))
        n_nodes -= 1

    T = defaultdict(int)
    T_parent = {}
    for e in edges:
        v, u = e
        if v in T:
            if len(T[v]) == 1:
                T[v] = u
            else:
                idx = random.randint(0, len(T[v]) - 1)
                T[u] = T[v][idx]
        else:
            T[v] = u
        T_parent[u] = v

    probs = {}
    for i in range(n):
        probs[i] = 1

    for e in edges:
        p = 0
        for v in [e[0], e[1]]:
            if v != e[0] or v != e[1]:
                p += (n + 1 - len(T[v])) / (n + 1 - len(T[v])) ** 2
        p /= len(edges)
        probs[T[e[0]]] -= p / len(edges)
        probs[T[e[1]]] -= p / len(edges)

    for p in probs.values():
        if p >= 0:
            p = x(x(10, -p))
        probs[p] = p

    return list(probs.values())

